\begin{frame}{Infinitesimal Model of Mutation}
  \begin{itemize}
    \item 突变每代贡献的加性方差 \$\textbackslash\{\}sigma\_m\textasciicircum{}2 = 2\textbackslash\{\}sum \textbackslash\{\}mu\_i \textbackslash\{\}sigma\textasciicircum{}2(\textbackslash\{\}alpha\_i)\$
    \item 遗传方差动态：\$\textbackslash\{\}sigma\_A\textasciicircum{}2(t)\textbackslash\{\}simeq 2N\_e\textbackslash\{\}sigma\_m\textasciicircum{}2 + [\textbackslash\{\}sigma\_A\textasciicircum{}2(0)-2N\_e\textbackslash\{\}sigma\_m\textasciicircum{}2]e\textasciicircum{}\{-t/2N\_e\}\$ (26.27)
    \item 仅由突变贡献的渐近响应率 \$r\_m(\textbackslash\{\}infty)=2N\_e\textbackslash\{\}bar\{\textbackslash\{\}imath\}\textbackslash\{\},\textbackslash\{\}sigma\_m\textasciicircum{}2/\textbackslash\{\}sigma\_z\$ (26.29)
    \item 达到渐近速率一半的时间 \$\textbackslash\{\}approx 1.4N\_e\$，与 \$\textbackslash\{\}sigma\_m\textasciicircum{}2\$ 无关
    \item 累积响应：\$R\_m(t)\textbackslash\{\}simeq 2N\_e\textbackslash\{\}bar\{\textbackslash\{\}imath\}\textbackslash\{\}frac\{\textbackslash\{\}sigma\_m\textasciicircum{}2\}\{\textbackslash\{\}sigma\_z\}\textbackslash\{\}big(t-2N\_e[1-e\textasciicircum{}\{-t/2N\_e\}]\textbackslash\{\}big)\$ (26.30a)
  \end{itemize}
\end{frame}

\begin{frame}{Crossover Time \$t\textasciicircum{}*\$}
  \kgimageplaceholder[figure=Figure 26.8,right,x=500,y=120,width=235,height=165]{Figure 26.8}
  \begin{itemize}
    \item \$t\textasciicircum{}*\$：每代突变响应等于剩余初始方差响应的时间
    \item \$t\textasciicircum{}* = 2N\_e\textbackslash\{\}ln(1+\textbackslash\{\}Psi)\$，其中 \$\textbackslash\{\}Psi = \textbackslash\{\}frac\{\textbackslash\{\}sigma\_A\textasciicircum{}2(0)\}\{2N\_e\textbackslash\{\}sigma\_m\textasciicircum{}2\}\$ (26.31a)
    \item 用 \$h\_m\textasciicircum{}2=\textbackslash\{\}sigma\_m\textasciicircum{}2/\textbackslash\{\}sigma\_E\textasciicircum{}2\$ 表达：\$\textbackslash\{\}Psi = \textbackslash\{\}dfrac\{h\textasciicircum{}2\}\{(1-h\textasciicircum{}2)2N\_e h\_m\textasciicircum{}2\}\$ (26.31b)
    \item 当 \$\textbackslash\{\}Psi \textbackslash\{\}ll 1\$，近似 \$t\textasciicircum{}*\textbackslash\{\}simeq h\textasciicircum{}2/[(1-h\textasciicircum{}2)h\_m\textasciicircum{}2]\$（约 200\$h\textasciicircum{}2/(1-h\textasciicircum{}2)\$ 当 \$h\_m\textasciicircum{}2=0.005\$）
    \item 高 \$h\textasciicircum{}2\$、小 \$N\_e\$ 时精确值低于近似值（见图 26.8）
  \end{itemize}
\end{frame}

